inputs.instruction:
Create two new entity factory files. JavaScript ESM. No dependencies. before: null for both.

File 1 — project/src/entities/taskDefinition.js:
Export createTaskDefinition(params) per SPEC §3.2.
params shape: { title, description, assignedTo, createdBy, dueAt, scheduleType='one-time', recurrenceRule=null, recurrenceStart=null, reminderMode='once', intervalSeconds=null, persistUntilSeconds=null }
Use crypto.randomUUID() for @id (no import needed — available as globalThis.crypto.randomUUID() in Node 19+).
Return JSON-LD object with ALL fields from SPEC §3.2:
  @context: 'https://schema.familytaskmanager.local/v1/'
  @type: 'ftm:TaskDefinition'
  @id: 'urn:ftm:task:' + crypto.randomUUID()
  ftm:title, ftm:description, ftm:assignedTo, ftm:createdBy
  ftm:createdAt: { '@type':'xsd:dateTime', '@value': new Date().toISOString() }
  ftm:version: 1
  ftm:updatedAt: { '@type':'xsd:dateTime', '@value': new Date().toISOString() }
  ftm:clientSequence: 1
  ftm:schedule: { '@type':'ftm:Schedule', 'ftm:scheduleType':params.scheduleType, 'ftm:dueAt':{'@type':'xsd:dateTime','@value':params.dueAt}, 'ftm:recurrenceRule':params.recurrenceRule, 'ftm:recurrenceStart':params.recurrenceStart }
  ftm:reminderPolicy: { '@type':'ftm:ReminderPolicy', 'ftm:mode':params.reminderMode, 'ftm:intervalSeconds':params.intervalSeconds, 'ftm:persistUntilSeconds':params.persistUntilSeconds }
  ftm:status: 'active'

File 2 — project/src/entities/taskInstance.js:
Export createTaskInstance(params) per SPEC §3.3.
params shape: { taskDefinitionId, assignedTo, dueAt }
Return JSON-LD with ALL fields from SPEC §3.3:
  @context: 'https://schema.familytaskmanager.local/v1/'
  @type: 'ftm:TaskInstance'
  @id: 'urn:ftm:instance:' + crypto.randomUUID()
  ftm:taskDefinition: params.taskDefinitionId
  ftm:assignedTo: params.assignedTo
  ftm:dueAt: { '@type':'xsd:dateTime', '@value':params.dueAt }
  ftm:createdAt: { '@type':'xsd:dateTime', '@value': new Date().toISOString() }
  ftm:updatedAt: { '@type':'xsd:dateTime', '@value': new Date().toISOString() }
  ftm:clientSequence: 1
  ftm:completionState: { '@type':'ftm:CompletionState', 'ftm:status':'pending', 'ftm:completedAt':null, 'ftm:completedBy':null, 'ftm:completedByRole':null }
  ftm:reminderSummary: { '@type':'ftm:ReminderSummary', 'ftm:totalSent':0, 'ftm:lastSentAt':null, 'ftm:lastDeliveryStatus':null, 'ftm:recentEvents':[] }
No I/O. No side effects.
